import java.util.*;

class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
        return (int) Arrays.stream(hours).filter(h -> h >= target).count();
    }
}

import java.util.Arrays;

class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
        Arrays.sort(hours);
        int left = 0;
        int right = hours.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (hours[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return hours.length - left;
    }
}

class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
        int[] frequency = new int[100001];
        for (int h : hours) {
            frequency[h]++;
        }
        int count = 0;
        for (int hour = target; hour <= 100000; hour++) {
            count += frequency[hour];
        }
        return count;
    }
}
